sp_widget.client_script:
api.controller = function($rootScope) {

    var c = this;

    c.activeItem = 'dashboard';

    c.selectMenu = function(menuName) {

        c.activeItem = menuName;

        $rootScope.$broadcast(
            'studentMenuChanged',
            menuName
        );

    };

};

sp_widget.css:
/*
 * ==========================================
 * STUDENT SIDEBAR
 * ==========================================
 */

.student-sidebar {

    width: 100%;

    min-height: 600px;

    background: #ffffff;

    border: 1px solid #e5e7eb;

    border-radius: 12px;

    overflow: hidden;

    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);

}


/*
 * ==========================================
 * HEADER
 * ==========================================
 */

.sidebar-header {

    padding: 20px;

    background: #f8fafc;

    border-bottom: 1px solid #e5e7eb;

}


.sidebar-title {

    font-size: 13px;

    font-weight: 700;

    letter-spacing: 0.8px;

    color: #334155;

}


.sidebar-subtitle {

    margin-top: 5px;

    font-size: 12px;

    color: #94a3b8;

}


/*
 * ==========================================
 * MENU CONTAINER
 * ==========================================
 */

.sidebar-menu {

    padding: 10px;

}


/*
 * ==========================================
 * MENU ITEM
 * ==========================================
 */

.sidebar-item {

    width: 100%;

    display: flex;

    align-items: center;

    gap: 12px;

    padding: 13px 14px;

    margin-bottom: 5px;

    border: none;

    border-radius: 8px;

    background: transparent;

    color: #475569;

    text-align: left;

    font-size: 14px;

    font-weight: 500;

    cursor: pointer;

    transition: all 0.2s ease;

}


/*
 * Remove default button outline
 */

.sidebar-item:focus {

    outline: none;

}


/*
 * ==========================================
 * ICON
 * ==========================================
 */

.menu-icon {

    width: 24px;

    min-width: 24px;

    text-align: center;

    font-size: 17px;

    color: #64748b;

}


/*
 * ==========================================
 * LABEL
 * ==========================================
 */

.menu-label {

    flex: 1;

}


/*
 * ==========================================
 * HOVER
 * ==========================================
 */

.sidebar-item:hover {

    background: #f1f5f9;

    color: #2563eb;

}


.sidebar-item:hover .menu-icon {

    color: #2563eb;

}


/*
 * ==========================================
 * ACTIVE ITEM
 * ==========================================
 */

.sidebar-item.active {

    background: #eff6ff;

    color: #2563eb;

    font-weight: 600;

}


.sidebar-item.active .menu-icon {

    color: #2563eb;

}


/*
 * ==========================================
 * MOBILE
 * ==========================================
 */

@media (max-width: 768px) {

    .student-sidebar {

        min-height: auto;

    }

    .sidebar-item {

        padding: 12px;

    }

}

sp_widget.link:
api.controller = function() {

    var c = this;

    // Default section
    c.activeSection = 'dashboard';


    // Change content section
    c.showSection = function(section) {

        c.activeSection = section;

    };

};
